import React, { useState, useEffect, useCallback } from 'react';

const DEFAULT_CHATS = [
  { id: 1, senderName: 'أحمد محمد', senderContact: '01012345678', message: 'مرحباً، هل الشقة في المعادي لا تزال متاحة؟', timestamp: new Date().toISOString() },
  { id: 2, senderName: 'سارة علي', senderContact: 'sara@example.com', message: 'أرغب في تحديد موعد لمعاينة الفيلا.', timestamp: new Date(Date.now() - 86400000).toISOString() },
  { id: 3, senderName: 'شركة التميز', senderContact: '0223456789', message: 'هل لديكم عروض تجارية للإيجار؟', timestamp: new Date(Date.now() - 172800000).toISOString() }
];

const AdminChat = ({ adminToken, adminInfo }) => {
  const [chats, setChats] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const fetchChats = useCallback(() => {
    setLoading(true);
    setError(null);
    fetch('/api/admin/chats', { headers: { 'x-admin-token': adminToken } })
      .then(res => {
        if (res.ok && res.headers.get('content-type')?.includes('application/json')) {
          return res.json();
        }
        throw new Error('تعذر تحميل الرسائل (قد يكون السيرفر متوقفاً)');
      })
      .then(data => {
        if (Array.isArray(data)) {
          setChats(data);
        } else {
          setChats([]);
        }
        setLoading(false);
      })
      .catch(err => {
        console.warn('Using mock data due to error:', err);
        // Fallback to mock data for demo/offline mode
        const saved = localStorage.getItem('adminChats');
        if (saved) {
          setChats(JSON.parse(saved));
        } else {
          setChats(DEFAULT_CHATS);
          localStorage.setItem('adminChats', JSON.stringify(DEFAULT_CHATS));
        }
        setLoading(false);
      });
  }, [adminToken]);

  useEffect(() => {
    fetchChats();
  }, [fetchChats]);

  const handleDelete = (chatId) => {
    if (!window.confirm('هل أنت متأكد من أنك تريد حذف هذه الرسالة؟')) return;

    // تحديث فوري للواجهة (Optimistic Update)
    const newChats = chats.filter(c => c.id !== chatId);
    setChats(newChats);
    localStorage.setItem('adminChats', JSON.stringify(newChats));

    fetch(`/api/admin/chats/${chatId}`, {
      method: 'DELETE',
      headers: { 'x-admin-token': adminToken }
    })
    .then(res => {
      if (!res.ok) {
        throw new Error('فشل في حذف الرسالة.');
      }
    })
    .catch(err => console.warn('Delete failed on server (mock mode active):', err.message));
  };

  const renderContent = () => {
    if (loading) {
      return <div className="text-center py-5">جاري تحميل الرسائل...</div>;
    }

    if (error) {
      return <div className="alert alert-danger m-3">{error}</div>;
    }

    if (chats.length === 0) {
      return (
        <div className="text-center text-muted py-5">
          <h3>لا توجد محادثات نشطة</h3>
          <p>عندما يبدأ العملاء محادثة، ستظهر هنا.</p>
        </div>
      );
    }

    return (
      <ul className="list-group list-group-flush">
        {chats.map((chat, index) => (
          <li key={chat.id} className="list-group-item d-flex justify-content-between align-items-start fade-in" style={{ animationDelay: `${index * 0.05}s` }}>
            <div className="ms-2 me-auto">
              <div className="fw-bold">{chat.senderName || 'مجهول'} - <small className="text-muted">{chat.senderContact}</small></div>
              {chat.message}
              <div className="text-muted small mt-2">{new Date(chat.timestamp).toLocaleString('ar-EG')}</div>
            </div>
            <button className="btn btn-outline-danger btn-sm" onClick={() => handleDelete(chat.id)}>
              حذف
            </button>
          </li>
        ))}
      </ul>
    );
  };

  return (
    <div className="row">
      <div className="col-12">
        <div className="card shadow-sm">
          <div className="card-header bg-dark text-white d-flex justify-content-between align-items-center">
            <h5 className="mb-0">رسائل العملاء</h5>
            <button className="btn btn-light btn-sm" onClick={fetchChats} disabled={loading}>
              {loading ? '...' : 'تحديث'}
            </button>
          </div>
          <div className="card-body p-0" style={{ minHeight: '400px' }}>
            {renderContent()}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminChat;
